package io.github.aihub.chat.controller;import io.github.aihub.chat.dto.*;import io.github.aihub.chat.service.*;import io.github.aihub.common.api.*;import jakarta.validation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import reactor.core.publisher.Flux;
@RestController @RequestMapping("/api/v1/ai") public class AIChatController{private final AIChatService s;public AIChatController(AIChatService s){this.s=s;}@PostMapping("/chat")public ApiResponse<ChatResponse> chat(@Valid @RequestBody ChatRequest r){return ApiResponse.success(s.chat(r));}@PostMapping(value="/chat/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE)public Flux<ChatStreamEvent> stream(@Valid @RequestBody ChatRequest r){return s.stream(r);}}